const CURRENT_VERSION: &str = "v1";
const V2_HELLO_PREFIX: &str = "v:2:hello:";

pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    match bytes {
        "ping" | "v1:ping" => Ok(Msg::Ping),
        _ if bytes.starts_with(V2_HELLO_PREFIX) => {
            Ok(Msg::Hello(bytes[V2_HELLO_PREFIX.len()..].to_owned()))
        }
        _ => {
            eprintln!("protocol decode error: unknown message body {bytes:?}");
            Err("unknown".into())
        }
    }
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => format!("{CURRENT_VERSION}:ping"),
        Msg::Hello(text) => format!("{V2_HELLO_PREFIX}{text}"),
    }
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    #[test]
    fn decodes_ping_forms() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
        assert!(matches!(decode("v1:ping"), Ok(Msg::Ping)));
    }

    #[test]
    fn decodes_v2_hello_envelope() {
        assert!(matches!(
            decode("v:2:hello:world"),
            Ok(Msg::Hello(text)) if text == "world"
        ));
        assert!(matches!(
            decode("v:2:hello:"),
            Ok(Msg::Hello(text)) if text.is_empty()
        ));
    }

    #[test]
    fn rejects_invalid_v2_envelopes() {
        assert!(decode("v2:hello:world").is_err());
        assert!(decode("v:2:hello").is_err());
    }

    #[test]
    fn encodes_v2_hello_envelope() {
        assert_eq!(encode(&Msg::Hello("world".into())), "v:2:hello:world");
    }

    #[test]
    fn roundtrips_hello_encoding() {
        let msg = Msg::Hello("hello:world".into());
        assert!(matches!(
            encode_roundtrip(&msg),
            Ok(Msg::Hello(text)) if text == "hello:world"
        ));
    }

    fn encode_roundtrip(msg: &Msg) -> Result<Msg, String> {
        decode(&encode(msg))
    }

    #[test]
    fn encodes_versioned_ping() {
        assert_eq!(encode(&Msg::Ping), "v1:ping");
    }

    #[test]
    fn roundtrips_ping_encoding() {
        assert!(matches!(encode_roundtrip(&Msg::Ping), Ok(Msg::Ping)));
    }
}
